MAP
  NAME "MRMS_Lightning"
  STATUS ON
  SIZE 800 600
  EXTENT -130.0 20.0 -60.0 55.0
  UNITS DD
  IMAGECOLOR 0 0 0

  PROJECTION
    "init=epsg:4326"
  END

  SYMBOLSET "/var/www/mapserver/symbols/symbols.map"

  WEB
    METADATA
      "wms_title"           "MRMS Lightning Probability 60min"
      "wms_onlineresource"  "http://209.248.90.253/wms/mrms_lightning"
      "wms_srs"             "EPSG:4326 EPSG:3857 EPSG:900913"
      "wms_enable_request"  "*"
      "wms_encoding"        "UTF-8"
      "wms_allow_getmap_without_styles" "true"
    END
  END

  OUTPUTFORMAT
    NAME "png"
    DRIVER "AGG/PNG"
    MIMETYPE "image/png"
    IMAGEMODE RGBA
    EXTENSION "png"
    TRANSPARENT ON
  END

  LAYER
    NAME "lightning"
    TYPE RASTER
    STATUS ON
    DATA "/var/www/mapserver/cache/lightning_current.grib2"

    PROJECTION
      "init=epsg:4326"
    END

    PROCESSING "NODATA=-999"

    CLASS
      NAME "0%"
      EXPRESSION ([pixel] < 5)
      STYLE
        COLOR 0 0 0
        OPACITY 0
      END
    END
    CLASS
      NAME "5-20%"
      EXPRESSION ([pixel] >= 5 AND [pixel] < 20)
      STYLE
        COLOR 255 255 100
        OPACITY 63
      END
    END
    CLASS
      NAME "20-40%"
      EXPRESSION ([pixel] >= 20 AND [pixel] < 40)
      STYLE
        COLOR 255 200 0
        OPACITY 75
      END
    END
    CLASS
      NAME "40-60%"
      EXPRESSION ([pixel] >= 40 AND [pixel] < 60)
      STYLE
        COLOR 255 140 0
        OPACITY 82
      END
    END
    CLASS
      NAME "60-80%"
      EXPRESSION ([pixel] >= 60 AND [pixel] < 80)
      STYLE
        COLOR 255 0 0
        OPACITY 86
      END
    END
    CLASS
      NAME ">=80%"
      EXPRESSION ([pixel] >= 80)
      STYLE
        COLOR 200 0 200
        OPACITY 90
      END
    END

    METADATA
      "wms_title" "MRMS Lightning Probability 60min"
      "wms_srs"   "EPSG:4326 EPSG:3857"
    END
  END
END
